import java.text.NumberFormat
import java.util.Locale

private val green = Color(0xFF236B4D)
private val mint = Color(0xFFE4F3E9)
private val ink = Color(0xFF14221D)
private val muted = Color(0xFF718078)
private val money = NumberFormat.getCurrencyInstance(Locale("en", "IN"))
data class Tx(val title: String, val category: String, val date: String, val amount: Long, val income: Boolean)
data class Loan(val lender: String, val balance: Long, val emi: Long, val due: String)

class MainActivity : ComponentActivity() {
 override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); setContent { FinanceApp() } }
}

@Composable fun FinanceApp() {
 var tab by remember { mutableStateOf("Home") }
 var add by remember { mutableStateOf(false) }
 var txs by remember { mutableStateOf(listOf(Tx("Monthly salary","Income","Today",65000,true),Tx("Grocery shopping","Food & groceries","Today",1840,false),Tx("Electricity bill","Bills","Yesterday",1250,false),Tx("Fuel","Transport","Yesterday",1800,false),Tx("Coffee shop","Food & drink","20 Oct",240,false))) }
 val loans = listOf(Loan("Fibe",31000,6200,"5 Nov"),Loan("KreditBee",24000,4800,"8 Nov"),Loan("Pocketly",12800,3200,"10 Nov"))
 val income = txs.filter { it.income }.sumOf { it.amount }; val expense = txs.filter { !it.income }.sumOf { it.amount }
 MaterialTheme(colorScheme = lightColorScheme(primary=green, background=Color(0xFFF6F8F5), surface=Color.White, onSurface=ink)) {
  Scaffold(containerColor=Color(0xFFF6F8F5), topBar={ Row(Modifier.fillMaxWidth().background(Color.White).statusBarsPadding().padding(16.dp), verticalAlignment=Alignment.CenterVertically) { Icon(Icons.Default.AccountBalanceWallet,null,tint=green,modifier=Modifier.size(30.dp)); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text("OPEN FINANCE",color=muted,fontSize=11.sp,letterSpacing=2.sp); Text("Your money, clearly.",color=ink,fontSize=18.sp,fontWeight=FontWeight.Bold) }; IconButton(onClick={tab="Settings"}) { Icon(Icons.Default.Settings,"Settings") } } },
  bottomBar={ NavigationBar(containerColor=Color.White) { listOf("Home","Activity","Reports","Loans","Coach").forEach { name -> NavigationBarItem(selected=tab==name,onClick={tab=name},icon={ Icon(when(name){"Home"->Icons.Default.Home;"Activity"->Icons.Default.ReceiptLong;"Reports"->Icons.Default.BarChart;"Loans"->Icons.Default.AccountBalance;else->Icons.Default.AutoAwesome},name) },label={Text(name,fontSize=10.sp)}) } } },
  floatingActionButton={ if(tab=="Home"||tab=="Activity") FloatingActionButton(onClick={add=true},containerColor=green,contentColor=Color.White){Icon(Icons.Default.Add,"Add transaction")} }) { pad ->
   Box(Modifier.fillMaxSize().padding(pad)) { when(tab) {
    "Home" -> Home(income,expense,txs,{tab="Activity"},{add=true},{tab=it})
    "Activity" -> Listing(txs)
    "Reports" -> Reports(income,expense,txs)
    "Loans" -> LoanScreen(loans)
    "Coach" -> Coach(income,expense,loans.sumOf{it.emi})
    "Calendar" -> CalendarScreen(loans,txs)
    "Insights" -> Insights(income,expense,loans.sumOf{it.balance})
    "Credit health" -> InfoScreen("Credit health","No credit bureau score is connected. Check your official credit report, pay EMIs on time, and review unfamiliar accounts.",Icons.Default.VerifiedUser)
    "Categories" -> Categories()
    "Backup & security" -> InfoScreen("Backup & security","This prototype keeps demo data in memory only. Encrypted backup, restore and CSV import/export are not implemented yet. Do not use it as your only financial record.",Icons.Default.Security)
    else -> Settings { tab=it }
   } }
   if(add) AddDialog({add=false}) { title,amount,isIncome,category -> txs=listOf(Tx(title,category,"Just now",amount,isIncome))+txs; add=false }
  }
 }
}

@Composable private fun Home(income:Long,expense:Long,txs:List<Tx>,all:()->Unit,add:()->Unit,open:(String)->Unit) {
 LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(15.dp)) {
  item { Text("THURSDAY, OCTOBER 23",color=muted,fontSize=11.sp,letterSpacing=1.sp); Text("Good morning 👋",fontSize=26.sp,color=ink,fontWeight=FontWeight.Bold); Spacer(Modifier.height(4.dp)); Row(horizontalArrangement=Arrangement.spacedBy(8.dp)) { OutlinedButton(onClick={open("Calendar")}) { Icon(Icons.Default.CalendarMonth,null); Text(" Calendar") }; OutlinedButton(onClick={open("Insights")}) { Icon(Icons.Default.Insights,null); Text(" Insights") } } }
  item { Card(colors=CardDefaults.cardColors(containerColor=green),shape=RoundedCornerShape(24.dp)) { Column(Modifier.fillMaxWidth().padding(22.dp),verticalArrangement=Arrangement.spacedBy(12.dp)) { Text("TOTAL BALANCE",color=Color.White.copy(alpha=.8f),fontSize=12.sp,letterSpacing=1.sp); Text(money.format(income-expense),color=Color.White,fontSize=32.sp,fontWeight=FontWeight.Bold); Text("Across your tracked finances",color=Color.White.copy(alpha=.8f),fontSize=12.sp); HorizontalDivider(color=Color.White.copy(alpha=.25f)); Row { Column(Modifier.weight(1f)) { Text("↓ INCOME",color=Color.White.copy(alpha=.8f)); Text(money.format(income),color=Color.White,fontWeight=FontWeight.Bold) }; Column(Modifier.weight(1f)) { Text("↑ EXPENSES",color=Color.White.copy(alpha=.8f)); Text(money.format(expense),color=Color.White,fontWeight=FontWeight.Bold) } } } } }
  item { Row(horizontalArrangement=Arrangement.spacedBy(9.dp)) { Quick("Add expense",Icons.Default.Remove,Modifier.weight(1f),add); Quick("Add income",Icons.Default.Add,Modifier.weight(1f),add); Quick("AI coach",Icons.Default.AutoAwesome,Modifier.weight(1f)){open("Coach")} } }
  item { Heading("Monthly overview","October 2026") }
  item { Card(colors=CardDefaults.cardColors(containerColor=Color.White),shape=RoundedCornerShape(18.dp)) { Column(Modifier.padding(17.dp),verticalArrangement=Arrangement.spacedBy(10.dp)) { Text("Spending this month",color=muted); Text(money.format(expense),fontSize=25.sp,fontWeight=FontWeight.Bold,color=ink); LinearProgressIndicator(progress={if(income>0)(expense.toFloat()/income).coerceIn(0f,1f) else 0f},modifier=Modifier.fillMaxWidth(),color=green,trackColor=mint); Text(if(income>0) (expense*100/income).toString()+"% of tracked income spent" else "Add income to see spending ratio",color=muted,fontSize=12.sp); Text("Open monthly report →",Modifier.clickable{open("Reports")},color=green) } } }
  item { Heading("Recent transactions","See all",all) }; items(txs.take(4)){TxRow(it)}
  item { Card(colors=CardDefaults.cardColors(containerColor=Color(0xFFEEF2FF)),shape=RoundedCornerShape(18.dp),modifier=Modifier.clickable{open("Coach")}) { Row(Modifier.padding(17.dp),verticalAlignment=Alignment.CenterVertically) { Icon(Icons.Default.AutoAwesome,null,tint=Color(0xFF5A62B5)); Spacer(Modifier.width(12.dp)); Column { Text("Your AI finance coach",fontWeight=FontWeight.Bold,color=ink); Text("Get a clearer view of your money habits.",fontSize=12.sp,color=muted) } } } }
  item { OutlinedButton(onClick={open("Credit health")},modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.Speed,null);Text(" Credit health")} }
 }
}
@Composable private fun Quick(label:String,icon:androidx.compose.ui.graphics.vector.ImageVector,mod:Modifier=Modifier,onClick:()->Unit){ Card(modifier=mod.clickable{onClick()},colors=CardDefaults.cardColors(containerColor=Color.White),shape=RoundedCornerShape(15.dp)){Column(Modifier.fillMaxWidth().padding(12.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(icon,null,tint=green);Text(label,color=ink,fontSize=11.sp,fontWeight=FontWeight.SemiBold)}} }
@Composable private fun Heading(title:String,action:String,onClick:()->Unit={}){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text(title,Modifier.weight(1f),fontSize=18.sp,color=ink,fontWeight=FontWeight.Bold);Text(action,Modifier.clickable{onClick()},color=green,fontSize=12.sp)}}
@Composable private fun TxRow(t:Tx){Row(Modifier.fillMaxWidth().background(Color.White,RoundedCornerShape(15.dp)).padding(13.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(42.dp).background(if(t.income)mint else Color(0xFFF6F8F5),RoundedCornerShape(13.dp)),contentAlignment=Alignment.Center){Icon(if(t.income)Icons.Default.Payments else Icons.Default.ShoppingBag,null,tint=green)};Spacer(Modifier.width(11.dp));Column(Modifier.weight(1f)){Text(t.title,color=ink,fontWeight=FontWeight.SemiBold);Text(t.category+" · "+t.date,color=muted,fontSize=11.sp)};Text((if(t.income)"+" else "−")+money.format(t.amount),color=if(t.income)green else ink,fontWeight=FontWeight.Bold,fontSize=12.sp)}}
@Composable private fun Listing(txs:List<Tx>){LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(11.dp)){item{Text("Transactions",fontSize=27.sp,color=ink,fontWeight=FontWeight.Bold);Text("Your tracked money activity",color=muted)};items(txs){TxRow(it)}}}
@Composable private fun Reports(income:Long,expense:Long,txs:List<Tx>){LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("Monthly reports",fontSize=27.sp,color=ink,fontWeight=FontWeight.Bold);Text("Income, spending and cash flow",color=muted)};item{Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){Metric("Income",money.format(income),Modifier.weight(1f));Metric("Expenses",money.format(expense),Modifier.weight(1f))}};item{Card(colors=CardDefaults.cardColors(containerColor=Color.White)){Column(Modifier.padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Text("Income vs expenses",fontWeight=FontWeight.Bold,color=ink);Text("Income  "+money.format(income),color=green);LinearProgressIndicator(progress={1f},color=green,modifier=Modifier.fillMaxWidth());Text("Expenses  "+money.format(expense),color=Color(0xFFB87532));LinearProgressIndicator(progress={if(maxOf(income,expense)>0)expense.toFloat()/maxOf(income,expense) else 0f},color=Color(0xFFE99B51),modifier=Modifier.fillMaxWidth());Text("Net cash flow: "+money.format(income-expense),fontSize=22.sp,fontWeight=FontWeight.Bold,color=ink)}}};item{Heading("Category breakdown","This month")};items(txs.filter{!it.income}.groupBy{it.category}.map{it.key to it.value.sumOf(Tx::amount)}){(category,amount)->Row(Modifier.fillMaxWidth().background(Color.White,RoundedCornerShape(14.dp)).padding(15.dp)){Text(category,Modifier.weight(1f),color=ink);Text(money.format(amount),color=ink,fontWeight=FontWeight.Bold)}}}}
@Composable private fun Metric(title:String,value:String,mod:Modifier){Card(mod,colors=CardDefaults.cardColors(containerColor=Color.White),shape=RoundedCornerShape(16.dp)){Column(Modifier.padding(14.dp)){Text(title,color=muted);Text(value,color=green,fontWeight=FontWeight.Bold,fontSize=18.sp)}}}
@Composable private fun LoanScreen(loans:List<Loan>){LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(13.dp)){item{Text("Loans & EMIs",fontSize=27.sp,color=ink,fontWeight=FontWeight.Bold);Text("Keep every repayment in view",color=muted)};item{Card(colors=CardDefaults.cardColors(containerColor=green),shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(20.dp)){Text("TOTAL OUTSTANDING",color=Color.White.copy(alpha=.8f));Text(money.format(loans.sumOf{it.balance}),fontSize=29.sp,color=Color.White,fontWeight=FontWeight.Bold);Text("Monthly EMIs · "+money.format(loans.sumOf{it.emi}),color=Color.White)}}};items(loans){loan->Card(colors=CardDefaults.cardColors(containerColor=Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(17.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.AccountBalance,null,tint=green);Spacer(Modifier.width(10.dp));Text(loan.lender,Modifier.weight(1f),color=ink,fontWeight=FontWeight.Bold);Text(money.format(loan.balance),color=ink,fontWeight=FontWeight.Bold)};HorizontalDivider(color=mint);Text("Monthly EMI: "+money.format(loan.emi),color=muted);Text("Next due: "+loan.due,color=muted)}}};item{Text("Sample values for UI demonstration. Add real loan details before relying on repayment totals.",color=muted,fontSize=11.sp)}}}
@Composable private fun Coach(income:Long,expense:Long,emi:Long){var question by remember{mutableStateOf("")};var answer by remember{mutableStateOf("")};LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("AI finance coach",fontSize=27.sp,color=ink,fontWeight=FontWeight.Bold);Text("Guidance based on the numbers you track",color=muted)};item{Card(colors=CardDefaults.cardColors(containerColor=Color(0xFFEEF2FF)),shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(18.dp)){Icon(Icons.Default.AutoAwesome,null,tint=Color(0xFF5A62B5));Text("Your money snapshot",fontSize=18.sp,fontWeight=FontWeight.Bold,color=ink);Text("Income: "+money.format(income)+"\nExpenses: "+money.format(expense)+"\nMonthly EMIs: "+money.format(emi),color=ink);Text(if(income>0)"Tracked expenses are "+(expense*100/income).toString()+"% of income. Review recurring costs and keep an emergency buffer before making extra loan payments." else "Record your income and expenses for more useful guidance.",color=muted)}};item{OutlinedTextField(question,{question=it},modifier=Modifier.fillMaxWidth(),label={Text("Ask about saving, budget or loans")},minLines=2)};item{Button(onClick={answer=if(income==0L)"Start by recording your take-home income, essential bills and loan EMIs." else "After tracked expenses and EMIs, your estimated remaining amount is "+money.format(income-expense-emi)+". Review recurring categories, keep minimum payments current, and compare loan APRs and foreclosure charges before extra repayment."},modifier=Modifier.fillMaxWidth()){Text("Get guidance")}};if(answer.isNotBlank())item{Text(answer,Modifier.background(Color.White,RoundedCornerShape(16.dp)).padding(16.dp),color=ink)};item{Text("This starter coach uses local rules, not a live AI service or regulated financial advice.",color=muted,fontSize=11.sp)}}}
@Composable private fun CalendarScreen(loans:List<Loan>,txs:List<Tx>){LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Financial calendar",fontSize=27.sp,color=ink,fontWeight=FontWeight.Bold);Text("October 2026 · Upcoming reminders",color=muted)};item{Card(colors=CardDefaults.cardColors(containerColor=Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){Text("M    T    W    T    F    S    S",color=muted);(1..31 step 7).forEach{start->Text((start..(start+6).coerceAtMost(31)).joinToString("     "),Modifier.padding(vertical=8.dp),color=ink)}}}};item{Heading("Upcoming EMI reminders","Loans")};items(loans){Row(Modifier.fillMaxWidth().background(Color.White,RoundedCornerShape(14.dp)).padding(14.dp)){Column(Modifier.weight(1f)){Text(it.lender,color=ink,fontWeight=FontWeight.Bold);Text("Due "+it.due,color=muted,fontSize=12.sp)};Text(money.format(it.emi),color=ink,fontWeight=FontWeight.Bold)}};item{Heading("Recent transactions","")};items(txs.take(5)){TxRow(it)}}}
@Composable private fun Insights(income:Long,expense:Long,debt:Long){LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(13.dp)){item{Text("Financial insights",fontSize=27.sp,color=ink,fontWeight=FontWeight.Bold)};item{Metric("Net tracked cash flow",money.format(income-expense),Modifier.fillMaxWidth())};item{Metric("Tracked loan balance",money.format(debt),Modifier.fillMaxWidth())};item{InfoCard("Spending check",if(income>0)"You have tracked "+(expense*100/income).toString()+"% of income as expenses. Check that cash, card and recurring payments are recorded." else "Add income and expenses to calculate a spending ratio.",Icons.Default.PieChart)};item{InfoCard("Debt overview","Track each balance, APR, fee, minimum payment and due date. Compare total costs before refinancing.",Icons.Default.AccountBalance)};item{InfoCard("Emergency buffer","Build savings gradually for essential expenses, at a pace that fits your income and obligations.",Icons.Default.Savings)}}}
@Composable private fun InfoCard(title:String,body:String,icon:androidx.compose.ui.graphics.vector.ImageVector){Card(colors=CardDefaults.cardColors(containerColor=Color.White),shape=RoundedCornerShape(17.dp)){Row(Modifier.padding(16.dp),verticalAlignment=Alignment.Top){Icon(icon,null,tint=green);Spacer(Modifier.width(12.dp));Column{Text(title,color=ink,fontWeight=FontWeight.Bold);Spacer(Modifier.height(5.dp));Text(body,color=muted,fontSize=13.sp)}}}}
@Composable private fun Categories(){val names=listOf("Food & groceries","Housing","Transport","Bills & utilities","Health","Shopping","Entertainment","Education","Loan repayment","Salary","Other income");LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){item{Text("Categories",fontSize=27.sp,color=ink,fontWeight=FontWeight.Bold);Text("Income and expense groups",color=muted)};items(names){Row(Modifier.fillMaxWidth().background(Color.White,RoundedCornerShape(14.dp)).padding(15.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Label,null,tint=green);Spacer(Modifier.width(12.dp));Text(it,color=ink)}};item{Text("Editing and saved custom categories are planned for a later pass.",color=muted,fontSize=11.sp)}}}
@Composable private fun Settings(open:(String)->Unit){LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Settings",fontSize=27.sp,color=ink,fontWeight=FontWeight.Bold);Text("Personalize your workspace",color=muted)};item{InfoCard("Preferences","Currency: Indian Rupee (₹)\nTheme: Light\nStorage: demo in memory",Icons.Default.Tune)};listOf("Categories" to Icons.Default.Label,"Calendar" to Icons.Default.CalendarMonth,"Insights" to Icons.Default.Insights,"Credit health" to Icons.Default.Speed,"Backup & security" to Icons.Default.Security).forEach{(label,icon)->item{Row(Modifier.fillMaxWidth().background(Color.White,RoundedCornerShape(14.dp)).clickable{open(label)}.padding(16.dp),verticalAlignment=Alignment.CenterVertically){Icon(icon,null,tint=green);Spacer(Modifier.width(12.dp));Text(label,Modifier.weight(1f),color=ink);Icon(Icons.Default.ChevronRight,null,tint=muted)}}};item{Text("Open Finance AI · Prototype 1.0.0",color=muted,fontSize=11.sp)}}}
@Composable private fun AddDialog(close:()->Unit,save:(String,Long,Boolean,String)->Unit){var title by remember{mutableStateOf("")};var amount by remember{mutableStateOf("")};var category by remember{mutableStateOf("Food & groceries")};var income by remember{mutableStateOf(false)};var error by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("Add transaction")},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){FilterChip(!income,{income=false},label={Text("Expense")});FilterChip(income,{income=true},label={Text("Income")})};OutlinedTextField(title,{title=it},label={Text("Description")},singleLine=true);OutlinedTextField(amount,{amount=it.filter{c->c.isDigit()}},label={Text("Amount (₹)")},singleLine=true);OutlinedTextField(category,{category=it},label={Text("Category")},singleLine=true);if(error.isNotBlank())Text(error,color=Color.Red)}},confirmButton={TextButton(onClick={val n=amount.toLongOrNull();if(title.isBlank()||n==null||n<=0)error="Enter a description and valid amount." else save(title.trim(),n,income,if(income)"Income" else category.ifBlank{"Other"})}){Text("Save")}},dismissButton={TextButton(onClick=close){Text("Cancel")}})}
